#!/usr/bin/env node
// Builds content/wordle/valid.json and content/wordle/answers.json.
//
//   node content/wordle/build.mjs
//       Normal build. Reads only files in content/wordle/source/ and content/wordle/curation/.
//
//   node content/wordle/build.mjs --hunspell <tr_TR.dic> <tr_TR.aff>
//       Re-extracts source/hunspell-tr-5.txt (all 5-letter surface forms generated by the
//       tdd-ai/hunspell-tr dictionary) from the raw ~36 MB hunspell files, then builds.
//
//   node content/wordle/build.mjs --subtitles <tr_full.txt>
//       Re-extracts source/opensubtitles-tr-5.txt (5-letter words + counts) from the raw
//       ~30 MB hermitdave/FrequencyWords tr_full.txt, then builds.
//
//   (Both flags can be combined.)
//
// Source files are treated as plain data: they are only read and parsed here, never executed.
// See README.md for sources, licenses and filtering rules.

import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const HERE = dirname(fileURLToPath(import.meta.url));
const SRC = join(HERE, 'source');
const CUR = join(HERE, 'curation');

const TR_ALPHABET = 'abcçdefgğhıijklmnoöprsştuüvyz';
const LETTER_RE = new RegExp(`^[${TR_ALPHABET}]{5}$`, 'u');
const LEN = 5;

const cpLen = (s) => [...s].length;
const trLower = (s) => s.toLocaleLowerCase('tr');
// â î û (and their uppercase forms, after lowercasing) are not on the keyboard -> a i u.
const normCirc = (s) => s.replace(/â/g, 'a').replace(/î/g, 'i').replace(/û/g, 'u');
const norm = (s) => normCirc(trLower(s.normalize('NFC').trim()));
const isWord5 = (w) => cpLen(w) === LEN && LETTER_RE.test(w);
const readLines = (p) => readFileSync(p, 'utf8').replace(/^﻿/, '').split(/\r?\n/);
const readList = (p) =>
  existsSync(p)
    ? readLines(p).flatMap((l) => l.replace(/#.*/, '').trim().split(/\s+/)).filter(Boolean).map(norm)
    : [];
const trSort = (arr) => [...arr].sort((a, b) => a.localeCompare(b, 'tr'));

// ---------------------------------------------------------------------------
// Optional step: extract 5-letter forms from the raw hunspell dictionary.
// tdd-ai/hunspell-tr uses FLAG num; every SFX rule is a single "strip 0, condition ."
// rule, so a surface form is simply stem + affix. We still honour strip/condition in
// case a later version changes that. Only cross-product-free suffixes are used (no PFX).
function extractHunspell(dicPath, affPath) {
  const rules = new Map(); // flag -> [{strip, add, cond}]
  for (const line of readLines(affPath)) {
    const p = line.trim().split(/\s+/);
    if (p[0] !== 'SFX' || p.length < 5) continue;
    const [, flag, strip, addRaw, cond] = p;
    const add = addRaw.split('/')[0]; // continuation flags ignored (none in this dictionary)
    const list = rules.get(flag) ?? [];
    list.push({
      strip: strip === '0' ? '' : strip,
      add: add === '0' ? '' : add,
      cond: cond === '.' ? null : new RegExp(`${cond}$`, 'u'),
    });
    rules.set(flag, list);
  }
  const out = new Set();
  const lines = readLines(dicPath);
  for (let i = 1; i < lines.length; i++) {
    const line = lines[i].trim();
    if (!line) continue;
    const slash = line.indexOf('/');
    const stem = slash < 0 ? line : line.slice(0, slash);
    const flags = slash < 0 ? [] : line.slice(slash + 1).split(/\s/)[0].split(',');
    const cands = [stem];
    const stemLen = cpLen(stem);
    if (stemLen <= LEN + 3) {
      for (const f of flags) {
        for (const r of rules.get(f) ?? []) {
          if (r.cond && !r.cond.test(stem)) continue;
          if (r.strip && !stem.endsWith(r.strip)) continue;
          const base = r.strip ? stem.slice(0, stem.length - r.strip.length) : stem;
          if (cpLen(base) + cpLen(r.add) !== LEN) continue;
          cands.push(base + r.add);
        }
      }
    }
    for (const c of cands) if (cpLen(c) === LEN) out.add(c.normalize('NFC'));
  }
  const header = [
    '# 5-letter surface forms generated from tdd-ai/hunspell-tr (MPL-2.0)',
    '# https://github.com/tdd-ai/hunspell-tr  (tr_TR.dic + tr_TR.aff)',
    '# Generated by content/wordle/build.mjs --hunspell. Unfiltered (may contain proper nouns etc.).',
  ];
  writeFileSync(join(SRC, 'hunspell-tr-5.txt'), header.concat(trSort(out)).join('\n') + '\n');
  console.log(`hunspell: wrote ${out.size} raw 5-letter forms to source/hunspell-tr-5.txt`);
}

// Optional step: extract 5-letter words (with counts) from the raw OpenSubtitles frequency list.
function extractSubtitles(fullPath) {
  const counts = new Map();
  for (const line of readLines(fullPath)) {
    const [w, n] = line.trim().split(' ');
    if (!w || !n) continue;
    const k = norm(w);
    if (!isWord5(k)) continue;
    counts.set(k, (counts.get(k) ?? 0) + Number(n));
  }
  const rows = [...counts].sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0], 'tr'));
  const header = [
    '# 5-letter words (Turkish alphabet, tr-lowercased, â/î/û -> a/i/u) with occurrence counts',
    '# from hermitdave/FrequencyWords content/2018/tr/tr_full.txt (OpenSubtitles 2018), CC BY-SA 4.0',
    '# Generated by content/wordle/build.mjs --subtitles.',
  ];
  writeFileSync(
    join(SRC, 'opensubtitles-tr-5.txt'),
    header.concat(rows.map(([w, n]) => `${w} ${n}`)).join('\n') + '\n',
  );
  console.log(`subtitles: wrote ${rows.length} 5-letter words to source/opensubtitles-tr-5.txt`);
}

const argv = process.argv.slice(2);
for (let i = 0; i < argv.length; i++) {
  if (argv[i] === '--hunspell') {
    if (!argv[i + 2]) throw new Error('usage: build.mjs --hunspell <tr_TR.dic> <tr_TR.aff>');
    extractHunspell(argv[i + 1], argv[i + 2]);
    i += 2;
  } else if (argv[i] === '--subtitles') {
    if (!argv[i + 1]) throw new Error('usage: build.mjs --subtitles <tr_full.txt>');
    extractSubtitles(argv[i + 1]);
    i += 1;
  } else throw new Error(`unknown argument ${argv[i]}`);
}

// ---------------------------------------------------------------------------
// 1) Wiktionary lemma list (atmanat/random-wordlist-tr, trlist-orig.txt).
//    Capitalised entries are proper nouns (Abana, Ankara...) -> used as a blocklist.
const wikLemmas = new Set(); // lowercase single-word lemmas, normalised
const wikProper = new Set(); // lemmas that only appear capitalised
const wikVerbStems = new Set(); // "anlatmak" -> "anlat"
for (const raw of readLines(join(SRC, 'trlist-orig.txt'))) {
  const line = raw.trim();
  if (!line || line.startsWith('#')) continue;
  if (/[\s\-'’.0-9]/u.test(line)) continue; // phrases, hyphenated, apostrophes, abbreviations
  const first = [...line][0];
  const capital = first !== first.toLocaleLowerCase('tr');
  if (capital) {
    // All-caps entries (e.g. "TDK") are abbreviations; mixed case = proper noun.
    wikProper.add(norm(line));
    continue;
  }
  const w = norm(line);
  wikLemmas.add(w);
  const m = w.match(/^(.+)(mak|mek)$/u);
  if (m) wikVerbStems.add(m[1]);
}
for (const w of wikLemmas) wikProper.delete(w); // e.g. "Mart" vs "mart": keep common noun

// 2) Hunspell 5-letter forms.
const hunspell = new Set(readList(join(SRC, 'hunspell-tr-5.txt')));

// 3) Frequency list (hermitdave/FrequencyWords, OpenSubtitles 2018, 5-letter subset of tr_full.txt).
const freq = new Map();
for (const line of readLines(join(SRC, 'opensubtitles-tr-5.txt'))) {
  if (line.startsWith('#')) continue;
  const [w, n] = line.trim().split(' ');
  if (w && n) freq.set(w, Number(n));
}

// 4) Manual curation lists.
const validExclude = new Set(readList(join(CUR, 'valid-exclude.txt')));
const validInclude = readList(join(CUR, 'valid-include.txt'));
const answersExclude = new Set(readList(join(CUR, 'answers-exclude.txt')));
const answersInclude = readList(join(CUR, 'answers-include.txt'));

// ---------------------------------------------------------------------------
// valid.json = ((hunspell forms ∩ seen in subtitles ≥ VALID_MIN_FREQ times)
//               ∪ Wiktionary lemmas ∪ Wiktionary verb stems ∪ manual includes)
//              − proper nouns (Wiktionary capitalised-only) − manual exclusions
// The hunspell dictionary is a compressed full-form list whose "stems" are arbitrary prefixes
// (e.g. "abanm" + a/ak), and it contains lowercased names/abbreviations ("abd" + "ca").
// Requiring subtitle evidence removes almost all of that noise, and requiring hunspell
// removes subtitle typos / foreign words.
const VALID_MIN_FREQ = Number(process.env.WORDLE_VALID_MIN_FREQ ?? 5);
const valid = new Set();
const addValid = (w) => {
  if (isWord5(w) && !wikProper.has(w) && !validExclude.has(w)) valid.add(w);
};
for (const w of hunspell) if ((freq.get(w) ?? 0) >= VALID_MIN_FREQ) addValid(w);
for (const w of wikLemmas) addValid(w);
for (const w of wikVerbStems) addValid(w);
for (const w of validInclude) if (isWord5(w)) valid.add(w);

// answers.json = base words (Wiktionary lemma or verb stem), in valid, frequent enough in
//                subtitles, minus the hand-curated exclusion list, plus hand-picked additions.
const MIN_FREQ = Number(process.env.WORDLE_MIN_FREQ ?? 60);
const answers = new Set();
for (const w of new Set([...wikLemmas, ...wikVerbStems])) {
  if (!valid.has(w)) continue;
  if ((freq.get(w) ?? 0) < MIN_FREQ) continue;
  if (answersExclude.has(w)) continue;
  answers.add(w);
}
for (const w of answersInclude) {
  if (!isWord5(w)) throw new Error(`answers-include: bad word "${w}"`);
  valid.add(w);
  answers.add(w);
}

const validArr = trSort(valid);
const answersArr = trSort(answers);
writeFileSync(join(HERE, 'valid.json'), JSON.stringify(validArr) + '\n');
writeFileSync(join(HERE, 'answers.json'), JSON.stringify(answersArr, null, 0) + '\n');
console.log(`valid.json:   ${validArr.length} words`);
console.log(`answers.json: ${answersArr.length} words (MIN_FREQ=${MIN_FREQ})`);
